def compute(vars):
    fair_value = vars["v1"]
    total_loans_held_for_sale = vars["v2"]

    if total_loans_held_for_sale == 0:
        return None

    value = fair_value / total_loans_held_for_sale * 100

    return {
        "value": value,
        "trace": {
            "fair_value": fair_value,
            "total_loans_held_for_sale": total_loans_held_for_sale,
            "ratio": fair_value / total_loans_held_for_sale,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
